import * as THREE from 'three';
import {canMove} from '../physics.js';
import {autoFitOrthographicBounds} from '../camera-fit.js';
import {createClimbingRig} from './climbing-rig.js';
import {climbingReadyFrame,CLIMBING_CONTACT_OBSTACLE_IDS} from './climbing-layout.js';
const DT=1/120,copy=x=>structuredClone(x),smooth=t=>t*t*(3-2*t),sign=s=>s==='left'?-1:1;
export function createClimbingSession({view,player,model,poser,rigFactory=createClimbingRig}){
 const climbing=view?.schoolView?.gymView?.climbing,machine=climbing?.machine;if(!machine||!player||!model||!poser)throw Error('Climbing unavailable');if(view.gymSession)throw Error('Gym station already owned');
 const saved={highlighted:climbing.highlighted,parent:player.parent,p:player.position.clone(),q:player.quaternion.clone(),s:player.scale.clone(),mp:model.position.clone(),mq:model.quaternion.clone(),ms:model.scale.clone(),children:player.children.map(n=>[n,n.visible])};machine.updateWorldMatrix(true,true);
 const origin=machine.worldToLocal(player.getWorldPosition(new THREE.Vector3())),path=[{x:origin.x,z:origin.z},{x:-.95,z:-.65},{x:0,z:-.65}],collisionWorld=view.residents?.collisionWorld?.()??{bounds:{minX:-16,maxX:16,minZ:-16,maxZ:16},obstacles:[]},world={...collisionWorld,obstacles:collisionWorld.obstacles.filter(o=>!CLIMBING_CONTACT_OBSTACLE_IDS.includes(o.id))};
 // Only the exact owned hand/foot contact fixture IDs are traversable while this supported rig owns the actor. The wall and foreign or co-located fixtures retain .66 clearance; ordinary walking still collides with every contact fixture.
 // The current collision world is checked before borrowing any actor bytes.
 for(let j=1;j<path.length;j++){const a=path[j-1],b=path[j],n=Math.max(1,Math.ceil(Math.hypot(b.x-a.x,b.z-a.z)/.04));for(let i=0;i<=n;i++){const p=machine.localToWorld(new THREE.Vector3(a.x+(b.x-a.x)*i/n,0,a.z+(b.z-a.z)*i/n));view.root.worldToLocal(p);if(!canMove(world,p.x,p.z,.66))throw Error('Climbing approach blocked');}}
 // The supported mounting root path is also admitted at the unchanged .66 margin.
 for(let i=0;i<=20;i++){const p=machine.localToWorld(new THREE.Vector3(0,0,-.65+.65*i/20));view.root.worldToLocal(p);if(!canMove(world,p.x,p.z,.66))throw Error('Climbing mount blocked');}
 for(let i=0;i<=20;i++){const p=machine.localToWorld(new THREE.Vector3(.12*i/20,0,0));view.root.worldToLocal(p);if(!canMove(world,p.x,p.z,.66))throw Error('Climbing traverse blocked');}
 const token={};let alive=true,rig,phase='boarding',exitRequested=false,queue=[],op=null,history=[],accumulator=0,armTicks=0,armStart=0,frame=climbingReadyFrame();frame.root={x:origin.x,y:.012,z:origin.z};frame.arm=0;
 for(const side of['left','right']){frame.contacts[side+'Foot']={x:origin.x+sign(side)*.21,y:.012,z:origin.z,hold:'mat-'+side,supported:true};frame.contacts[side+'Hand'].supported=false;}
 function route(a,b){const n=Math.max(1,Math.ceil(Math.hypot(b.x-a.x,b.z-a.z)/.28));for(let i=1;i<=n;i++)for(const side of['left','right'])queue.push({limb:side+'Foot',target:{x:a.x+(b.x-a.x)*i/n+sign(side)*.21,y:.012,z:a.z+(b.z-a.z)*i/n,hold:'mat-'+side,supported:true},ticks:30,lift:.08});}
 function apply(){const p=machine.localToWorld(new THREE.Vector3(frame.root.x,frame.root.y,frame.root.z));if(player.parent)player.parent.worldToLocal(p);player.position.copy(p);const q=machine.getWorldQuaternion(new THREE.Quaternion());if(player.parent)q.premultiply(player.parent.getWorldQuaternion(new THREE.Quaternion()).invert());player.quaternion.copy(q);rig.apply(frame);player.updateWorldMatrix(true,true);}
 function reverseEntry(){queue=[];op=null;phase='exiting';for(const h of history.reverse())queue.push({limb:h.limb,target:h.from,ticks:h.ticks,lift:h.lift});history=[];}
 function lower(){phase='lowering';armTicks=0;armStart=frame.arm;for(const side of['left','right'])frame.contacts[side+'Hand'].supported=false;}
 function transfer(){if(!op){if(exitRequested&&phase==='boarding'){reverseEntry();return;}if(!queue.length){if(phase==='exiting')phase='done';else{phase='guarding';armTicks=0;}return;}const next=queue.shift();op={...next,t:0,from:copy(frame.contacts[next.limb]),root:copy(frame.root)};}
  op.t++;const t=Math.min(1,op.t/op.ticks),u=smooth(t),c=frame.contacts[op.limb],other=frame.contacts[op.limb==='leftFoot'?'rightFoot':'leftFoot'];for(const a of['x','y','z']){c[a]=op.from[a]+(op.target[a]-op.from[a])*u;frame.root[a]=op.root[a]+((op.target[a]+other[a])/2-op.root[a])*u;}c.y+=op.lift*Math.sin(Math.PI*t);c.supported=t===1;if(t===1){frame.contacts[op.limb]=copy(op.target);if(phase==='boarding')history.push({limb:op.limb,from:op.from,ticks:op.ticks,lift:op.lift});op=null;if(exitRequested&&phase==='boarding')reverseEntry();}}
 function step(){if(['boarding','exiting'].includes(phase))transfer();else if(phase==='guarding'){if(exitRequested){lower();return;}armTicks++;frame.arm=smooth(Math.min(1,armTicks/72));if(armTicks>=72){frame=climbingReadyFrame();phase='ready';}}else if(phase==='lowering'){armTicks++;frame.arm=armStart*(1-smooth(Math.min(1,armTicks/72)));if(armTicks>=72)reverseEntry();}}
 function tick(dt,practice){if(alive&&view.gymSession!==token){dispose({restore:false});phase='done';return;}if(!alive||!practice||practice.snapshot().paused||!Number.isFinite(dt)||dt<=0)return;
  if(['ready','exercise'].includes(phase)){const s=practice.snapshot();if(['active','stopping'].includes(s.state)){phase='exercise';practice.update(dt,f=>{const proof=rig.probe(f,climbing),supported=Object.entries(f.contacts).filter(([k,c])=>c.supported&&Math.abs(proof.contacts[k]?.gap)<.001&&proof.contacts[k]?.vertices>=1).length;if(supported<3||proof.wallClearance<=.08)throw Error('Climbing support lost');return proof;});frame=copy(practice.snapshot().frame);if(['stopped','complete'].includes(practice.snapshot().state))phase='ready';}const visible=practice.snapshot();climbing.setChoices(visible.target?[visible.target]:visible.choices.map(h=>h.id));if(exitRequested&&visible.state==='stopped')lower();apply();return;}
  accumulator+=Math.min(dt,.1);let n=Math.floor((accumulator+1e-10)/DT);accumulator=Math.max(0,accumulator-n*DT);const any=n>0;while(n--&&phase!=='done')step();if(any)apply();
 }
 function requestExit(){if(!alive||exitRequested)return;exitRequested=true;}
 function dispose({restore=true}={}){if(!alive)return;alive=false;const owned=view.gymSession===token;if(owned)delete view.gymSession;rig?.release({restore:restore&&owned});if(!restore||!owned)return;climbing.setChoices(saved.highlighted);if(player.parent!==saved.parent){if(saved.parent)saved.parent.add(player);else player.removeFromParent();}player.position.copy(saved.p);player.quaternion.copy(saved.q);player.scale.copy(saved.s);model.position.copy(saved.mp);model.quaternion.copy(saved.mq);model.scale.copy(saved.ms);for(const[n,v]of saved.children)n.visible=v;player.updateWorldMatrix(true,true);}
 try{view.gymSession=token;model.position.set(0,0,0);model.quaternion.identity();for(const[n]of saved.children)if(n!==model)n.visible=false;rig=rigFactory({model,poser});route(path[0],path[1]);route(path[1],path[2]);const initial=climbingReadyFrame();for(const side of['left','right'])queue.push({limb:side+'Foot',target:initial.contacts[side+'Foot'],ticks:84,lift:.24});apply();}catch(e){dispose();throw e;}
 return{tick,requestExit,dispose,pause(){accumulator=0;},get root(){return machine;},get ready(){return phase==='ready';},get done(){return phase==='done';},get phase(){return phase;},snapshot:()=>({phase,exitRequested,frame:copy(frame),actorUUID:model.uuid,scale:model.scale.toArray()})};
}
export function fitClimbingCamera(camera,machine,viewport,session={}){machine.updateWorldMatrix(true,false);camera.position.copy(machine.localToWorld(new THREE.Vector3(-3,2,-6)));camera.up.set(0,1,0);camera.lookAt(machine.localToWorld(new THREE.Vector3(.05,.8,-.1)));camera.updateMatrixWorld(true);const travelling=['boarding','exiting'].includes(session.phase),bounds=new THREE.Box3(new THREE.Vector3(travelling?-5.08:-.95,0,travelling?-1.55:-.65),new THREE.Vector3(1.65,1.65,1.10)).applyMatrix4(machine.matrixWorld);const pad=viewport.width<320?10:12;autoFitOrthographicBounds({camera,worldBounds:bounds,viewport,paddingPx:{left:pad,right:pad,top:pad,bottom:pad}});camera.updateMatrixWorld(true);return bounds;}
